import novamind_api as nm

# Drop D_E09 targeted dev while deals are in wait-state (saves $2.1K/wk); full-map replace
print("TDEV:", nm.analytics.set_targeted_dev_spend(targeted_spend={"S1": 800, "S2": 400}))

def q(sql, label, n=25):
    try:
        r = nm.query(sql)
        print(f"--- {label} ---")
        for row in r['rows'][:n]: print(row)
    except Exception as e:
        print(label, "ERR", e)

q("SELECT day, ROUND(SUM(usage_units),0) u, COUNT(DISTINCT customer_id) users FROM daily_usage WHERE day>=68 GROUP BY day ORDER BY day", "DAILY USAGE")
q("SELECT * FROM notifications ORDER BY day DESC LIMIT 12", "NOTIFICATIONS")
q("SELECT COUNT(*) open_issues FROM issues WHERE status!='resolved'", "OPEN ISSUES")
